CREATE OR REPLACE FUNCTION public.processar_pontuacao_diaria()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user uuid := auth.uid();
  v_contratadas numeric;
  r RECORD; v_pct int; v_delta int;
BEGIN
  IF v_user IS NULL THEN RETURN; END IF;
  PERFORM set_config('app.scoring', '1', true);
  SELECT horas_dia_contratadas INTO v_contratadas FROM profiles WHERE id = v_user;
  IF v_contratadas IS NULL OR v_contratadas <= 0 THEN v_contratadas := 8; END IF;

  FOR r IN
    SELECT (reg.inicio AT TIME ZONE 'America/Sao_Paulo')::date AS dia,
           SUM(EXTRACT(EPOCH FROM (COALESCE(reg.fim, reg.inicio) - reg.inicio))/3600.0) AS horas
    FROM registros reg
    WHERE reg.user_id = v_user
      AND (reg.inicio AT TIME ZONE 'America/Sao_Paulo')::date
          < (now() AT TIME ZONE 'America/Sao_Paulo')::date
      AND NOT EXISTS (
        SELECT 1 FROM pontuacao_diaria pd
        WHERE pd.user_id = v_user
          AND pd.data = (reg.inicio AT TIME ZONE 'America/Sao_Paulo')::date)
    GROUP BY 1
  LOOP
    v_pct := LEAST(100, ROUND(100 * COALESCE(r.horas,0) / v_contratadas))::int;
    v_delta := CASE
      WHEN v_pct >= 100 THEN 5 WHEN v_pct >= 90 THEN 3
      WHEN v_pct >= 80 THEN 2  WHEN v_pct >= 70 THEN 1
      WHEN v_pct >= 60 THEN -1 WHEN v_pct >= 50 THEN -2 ELSE -5 END;
    INSERT INTO pontuacao_diaria (user_id, data, percentual, bateu_meta, moedas_delta)
    VALUES (v_user, r.dia, v_pct, v_pct >= 70, v_delta)
    ON CONFLICT (user_id, data) DO NOTHING;
    UPDATE profiles SET moedas = GREATEST(0, moedas + v_delta) WHERE id = v_user;
  END LOOP;
END; $function$

CREATE OR REPLACE FUNCTION public.protege_campos_perfil()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NOT NULL AND NOT public.is_admin() THEN
    NEW.role := OLD.role; NEW.ativo := OLD.ativo;
    NEW.area_id := OLD.area_id; NEW.email := OLD.email;
    IF current_setting('app.scoring', true) IS DISTINCT FROM '1' THEN
      NEW.moedas := OLD.moedas;  -- moedas só mudam via a função de pontuação
    END IF;
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
